// caras-en-rejilla v1.0 · BUG-CARAS1 — el interior de una pieza con `caras` vuelve a verse en el Mundo
//
// EL FALLO, tal cual lo contó el dueño: «el bloque «leaves» tampoco se pinta bien: en el mundo solo se
// ven las caras marcadas del exterior del cubo 16x16x16, pero no las interiores (antes se veían)».
//
// POR QUÉ. Una celda de `mc.grid` se dibuja de dos maneras y quién elige es `mcRecFina`:
//   · PROYECTADA — el dibujo se aplasta sobre las 6 caras del cubo (`buildTexFaces`) y va en el atlas del
//     terreno. Solo es fiel si la pieza es un MACIZO opaco (`blockLike`): lo que se ve del dibujo ES su
//     cáscara. Barato: cero draw calls.
//   · FINA — sus voxels de verdad, dentro de la malla del chunk (`mc._geoFina`). Fiel siempre.
// `leaves` cubre su celda (`pielCubre`) pero NO es `blockLike` —1548 voxels de 4096— y encima trae
// `caras`. Hoy cae en la proyección, y una proyección solo sabe de la piel: el interior no existe para
// ella. Antes no pasaba porque un material así ni siquiera entraba en la rejilla: se estampaba como pieza
// suelta, que sí es fina. Eso se perdió al ampliar mc.grid (BUG-STR1) y por eso es una REGRESIÓN.
//
// EL ARREGLO, en una frase: con `caras`, geometría de verdad. La proyección se queda para el macizo.
//
// ⛔ Esto NO toca `app.js` (ley de oro, docs/desarrollo-desacoplado.md). No hace falta ni envolver nada:
// el motor YA expone la válvula a mano —`mc.finoExtra`, 1 = fina, 2 = nunca— justo para esto. `off()`
// devuelve la tabla anterior tal cual estaba y vuelve a mallar, byte a byte.
//
//   game.carasRejilla.on()      // arreglado
//   game.carasRejilla.off()     // como estaba
//   game.carasRejilla.estado()  // qué materiales toca y en qué mano está
(function () {
  var G = game, M = {};
  M.VERSION = 'v1.0';

  // ¿Este material es de los que la proyección estropea? Es la condición de `mcRecFina` que hoy dice que
  // no (`pielCubre && conCaras`), y solo esa: lo que ya sale fino no se toca, y un macizo tampoco.
  M.leEstropea = function (rec) {
    return !!(rec && rec.w === 1 && rec.h === 1 && rec.d === 1 && !rec.blockLike && rec.conCaras &&
              rec.pielCubre && !mcRecFina(rec));
  };

  // Los ids de la paleta de ESTE mundo que hay que pasar a fina. `mcStructCells` es asíncrona la primera
  // vez; se espera aquí y no en el mallado, que es síncrono.
  M.afectados = async function () {
    var out = [];
    if (!mc.blockKey) return out;
    for (var id = 1; id < mc.blockKey.length; id++) {
      var key = mc.blockKey[id];
      if (!key || (key.indexOf('asset:') !== 0 && key.indexOf('hab:') !== 0)) continue;
      var base = mcClaveBase(key), rec = null;
      try { rec = await mcStructCells(base); } catch (e) { continue; }
      if (M.leEstropea(rec)) out.push({ id: id, key: key });
    }
    return out;
  };

  M.on = async function () {
    var lista = await M.afectados();
    if (!lista.length) { M.tocados = []; return 0; }
    // La tabla anterior se guarda ENTERA (o el `null` de «no había»): `off()` la devuelve sin reconstruir
    // nada, que es la única forma de garantizar que no queda rastro.
    if (M.previo === undefined) M.previo = mc.finoExtra ? mc.finoExtra.slice() : null;
    var n = mc.blockKey.length + 1;
    var ex = new Uint8Array(Math.max(n, mc.finoExtra ? mc.finoExtra.length : 0));
    if (mc.finoExtra) ex.set(mc.finoExtra);
    for (var i = 0; i < lista.length; i++) ex[lista[i].id] = 1;   // 1 = fina, y manda sobre mc.finoRejilla
    mc.finoExtra = ex;
    // `mcMeshChunk` es SÍNCRONO: sin la geometría ya horneada no emitiría nada y el bloque desaparecería
    // un instante. Se hornea aquí, con la misma llamada que usa mcBuildPalette.
    for (var j = 0; j < lista.length; j++) {
      var k = lista[j].key;
      if (!mc.finoGeom[k]) mc.finoGeom[k] = await mcStructGeom(mcClaveBase(k), mcClaveOri(k));
    }
    mcTablaFina();
    mcMeshAll();
    M.tocados = lista;
    return lista.length;
  };

  M.off = function () {
    if (M.previo === undefined) return false;    // nunca se encendió: no hay nada que deshacer
    mc.finoExtra = M.previo;
    M.previo = undefined;
    M.tocados = [];
    mcTablaFina();
    mcMeshAll();
    return true;
  };

  M.estado = function () {
    return {
      version: M.VERSION,
      puesto: M.previo !== undefined,
      materiales: (M.tocados || []).map(function (t) { return t.key; })
    };
  };

  G.carasRejilla = M;
})();

var _n = await game.carasRejilla.on();
toast('caras-en-rejilla: ' + _n + ' material(es) con máscara pasan a geometría fina');
